    {
        ID: 1, Icon: "Target",
        Value: CountRows(Filter(colRequests, !IsDeleted)),
        Label: "Total Requests", PercentChange: Blank(), PercentLabel: "",
        IconBg: "#DBEAFE", IconColor: "#1D4ED8", SparklineData: "", isHidden: false
    },
    {
        ID: 2, Icon: "Check",
        Value: CountRows(Filter(colRequests, StatusKey = "Completed", !IsDeleted)),
        Label: "Completed", PercentChange: Blank(), PercentLabel: "",
        IconBg: "#DCFCE7", IconColor: "#15803D", SparklineData: "", isHidden: false
    },
    {
        ID: 3, Icon: "Clock",
        Value: CountRows(Filter(colRequests, StatusKey = "InProgress", !IsDeleted)),
        Label: "In Progress", PercentChange: Blank(), PercentLabel: "",
        IconBg: "#FEF3C7", IconColor: "#B45309", SparklineData: "", isHidden: false
    },
    {
        ID: 4, Icon: "Warning",
        Value:
            CountRows(
                Filter(
                    colRequests,
                    !IsDeleted,
                    StatusKey <> "Completed",
                    !IsBlank(RequestDueDate),
                    RequestDueDate < Today()
                )
            ),
        Label: "Overdue", PercentChange: Blank(), PercentLabel: "",
        IconBg: "#FEE2E2", IconColor: "#B91C1C", SparklineData: "", isHidden: false
    }
)

