    Sort(nfCategories, SortOrder) As c,
    {
        Label: c.Title,
        Value: CountRows(Filter(colRequests, CategoryKey = c.ConfigKey, !IsDeleted)),
        Subtitle: "",
        isHidden: false
    }
)

